  "glossary": [
    {
      "front": "Meaning of Tissue",
      "back": "A tissue is a group of similar cells working together to perform a specific function."
    },
    {
      "front": "Plant Meristematic Tissue",
      "back": "Meristematic tissue contains actively dividing cells at growing regions of plants."
    },
    {
      "front": "Permanent Tissues",
      "back": "Permanent tissues arise from differentiated meristematic cells and perform specialised functions."
    },
    {
      "front": "Parenchyma",
      "back": "Parenchyma is a living, usually thin-walled simple permanent tissue involved in storage, photosynthesis or packing."
    },
    {
      "front": "Collenchyma",
      "back": "Collenchyma provides flexible mechanical support through living cells with unevenly thickened walls."
    },
    {
      "front": "Sclerenchyma",
      "back": "Sclerenchyma provides strong mechanical support through thick, usually lignified walls."
    },
    {
      "front": "Xylem",
      "back": "Xylem conducts water and dissolved minerals and also contributes to support."
    },
    {
      "front": "Phloem",
      "back": "Phloem transports prepared food, especially sugars, from sources to other parts of the plant."
    },
    {
      "front": "Epithelial Tissue",
      "back": "Epithelial tissue forms coverings and linings and may perform protection, absorption or secretion."
    },
    {
      "front": "Connective Tissue",
      "back": "Connective tissue supports, connects, binds or separates structures; its cells lie in an extracellular matrix."
    },
    {
      "front": "Muscular Tissue",
      "back": "Muscular tissue contains specialised contractile cells that produce movement."
    },
    {
      "front": "Nervous Tissue",
      "back": "Nervous tissue receives stimuli and transmits electrical signals through neurons and associated cells."
    },
    {
      "front": "Plant vs Animal Tissues",
      "back": "Plant tissues are adapted mainly for growth, support, transport and photosynthesis, while animal tissues are specialised for protection, connection, movement and communication."
    },
    {
      "front": "Division of Labour",
      "back": "Division of labour distributes different functions among specialised cells and tissues, increasing efficiency in multicellular organisms."
    },
    {
      "front": "Tissue Identification",
      "back": "Tissue identification uses structural clues such as cell shape, arrangement, wall thickness, location and specialised features."
    }
  ],
